## Approach
BFS over the grid: whenever I hit a `'1'` I increment the island count, then flood the whole component with a queue of cell coordinates, marking each visited cell as `'0'` so it never gets counted again. Each cell enters the queue once, so the walk is linear.

## Code
```go
func numIslands(grid [][]byte) int {
	if len(grid) == 0 || len(grid[0]) == 0 {
		return 0
	}
	rows, cols := len(grid), len(grid[0])
	dirs := [4][2]int{{1, 0}, {-1, 0}, {0, 1}, {0, -1}}
	count := 0

	for r := 0; r < rows; r++ {
		for c := 0; c < cols; c++ {
			if grid[r][c] != '1' {
				continue
			}
			count++
			grid[r][c] = '0'
			queue := [][2]int{{r, c}}

			for len(queue) > 0 {
				cur := queue[0]
				queue = queue[1:]

				for _, d := range dirs {
					nr, nc := cur[0]+d[0], cur[1]+d[1]
					if nr < 0 || nr >= rows || nc < 0 || nc >= cols {
						continue
					}
					if grid[nr][nc] != '1' {
						continue
					}
					grid[nr][nc] = '0'
					queue = append(queue, [2]int{nr, nc})
				}
			}
		}
	}
	return count
}
```

## Complexity
Time O(rows × cols): every cell is scanned once, and each land cell is enqueued and dequeued at most once. Space O(rows × cols) worst case for the queue (a whole island plus its frontier), plus the O(1) direction array.

```go
package lru

type node struct {
	key, val   int
	prev, next *node
}

type LRUCache struct {
	cap        int
	items      map[int]*node
	head, tail *node // head is most recently used
}

func Constructor(capacity int) LRUCache {
	return LRUCache{cap: capacity, items: make(map[int]*node, capacity)}
}

func (c *LRUCache) Get(key int) int {
	n, ok := c.items[key]
	if !ok {
		return -1
	}
	c.moveToFront(n)
	return n.val
}

func (c *LRUCache) Put(key, value int) {
	if n, ok := c.items[key]; ok {
		n.val = value
		c.moveToFront(n)
		return
	}
	n := &node{key: key, val: value}
	c.items[key] = n
	c.pushFront(n)
	if len(c.items) > c.cap {
		old := c.tail
		delete(c.items, old.key)
		c.remove(old)
	}
}

func (c *LRUCache) pushFront(n *node) {
	n.prev, n.next = nil, c.head
	if c.head != nil {
		c.head.prev = n
	}
	c.head = n
	if c.tail == nil {
		c.tail = n
	}
}

func (c *LRUCache) remove(n *node) {
	if n.prev != nil {
		n.prev.next = n.next
	} else {
		c.head = n.next
	}
	if n.next != nil {
		n.next.prev = n.prev
	} else {
		c.tail = n.prev
	}
	n.prev, n.next = nil, nil
}

func (c *LRUCache) moveToFront(n *node) {
	if c.head == n {
		return
	}
	c.remove(n)
	c.pushFront(n)
}
```

A map gives O(1) lookup, and a hand rolled doubly linked list keeps recency ordering in O(1) per touch, so eviction is just dropping the tail. Both Get and Put are O(1) time, and space is O(capacity).

